var payRunId = 1;
cy.xpath(Overview_page_1.OverviewPage.moreOption(payRunId)).click();
cy.xpath(Overview_page_1.OverviewPage.morelistItem("Create Off-cycle")).wait(1500).click();
cy.get("@payRunName").then(function ($payRunName) {
    var payRunNameSplit = $payRunName.split(" ");
    var payRunNameFormatted = payRunNameSplit.slice(0, payRunNameSplit.length - 3).join(" ") + ", " + payRunNameSplit.slice(payRunNameSplit.length - 3).join(" ");
    cy.get(CreateOffcycleDialog_page_1.CreateOffcycleDialogPage.CreateOffcycleDialog_Description_SourcePayRunPayRunName).should("have.text", payRunNameFormatted);
});
cy.get("@payPeriod").then(function ($payPeriod) {
    /*
    * const payPeriod = '3/19/2023 - 3/25/2023'
    * On the overview page, the date is given as StartDate - (EndDate minus 1 day)
    * On the create off-cycle page, the date is given as StartDate - EndDate
    * We need to parse the dates into Date Objects, make the addition of 1 day to the end date and stringify again
    */
    var startDateString = $payPeriod.split("-")[0].trim();
    var endDateString = $payPeriod.split("-")[1].trim(); // Get the end date as a string
    var endDateElements = endDateString.split("/").map(function ($elem) { return parseInt($elem); }); // Convert a date from '3/19/2023' to [3, 19, 2023]
    var endDateDateObj = new Date(endDateElements[2], endDateElements[0] - 1, endDateElements[1]);
    var trueEndDateDateObj = new Date(endDateDateObj.valueOf() + 86400000); // Adding one days worth of milliseconds
    var trueEndDateString = [
        (trueEndDateDateObj.getMonth() + 1).toString(),
        trueEndDateDateObj.getDate().toString(),
        trueEndDateDateObj.getFullYear().toString()
    ]
        .join("/");
    var finalPayPeriod = "".concat(startDateString, " - ").concat(trueEndDateString);
    cy.log(finalPayPeriod);
    cy.get(CreateOffcycleDialog_page_1.CreateOffcycleDialogPage.CreateOffcycleDialog_Description_SourcePayRunPayPeriod).should("have.text", finalPayPeriod);
});
cy.get("@payDate").then(function ($payDate) {
    cy.get(CreateOffcycleDialog_page_1.CreateOffcycleDialogPage.CreateOffcycleDialog_Description_SourcePayRunPayDate).should("have.text", $payDate);
});
cy.get("@commitDate").then(function ($commitDate) {
    cy.xpath(CreateOffcycleDialog_page_1.CreateOffcycleDialogPage.CreateOffcycleDialog_Description_SourcePayRunCommitDate).should("have.text", $commitDate);
});
